class {{class_name}}:
    def __init__(self, arr):
        n = len(arr)
        self.n = n
        self.t = [0]*(4*n)
        if n: self._build(arr, 1, 0, n-1)
    def _build(self, a, v, l, r):
        if l == r:
            self.t[v] = a[l]; return
        m = (l+r)//2
        self._build(a, v*2, l, m)
        self._build(a, v*2+1, m+1, r)
        self.t[v] = self.t[v*2] + self.t[v*2+1]
    def update(self, i, val, v=1, l=0, r=None):
        if r is None: r = self.n-1
        if l == r: self.t[v] = val; return
        m = (l+r)//2
        if i <= m: self.update(i, val, v*2, l, m)
        else: self.update(i, val, v*2+1, m+1, r)
        self.t[v] = self.t[v*2] + self.t[v*2+1]
    def query(self, ql, qr, v=1, l=0, r=None):
        if r is None: r = self.n-1
        if ql > r or qr < l: return 0
        if ql <= l and r <= qr: return self.t[v]
        m = (l+r)//2
        return self.query(ql, qr, v*2, l, m) + self.query(ql, qr, v*2+1, m+1, r)
